// --- UNIFORMS ---
uniform sampler2D uPreviousFrame;
uniform float uTime;
uniform vec2 uResolution;

// --- INPUT (From JavaScript) ---
uniform float e0E0E0Intensity;

// --- GEOMETRY & ROTATION ---
uniform float uDensity;       // 80.0  (Strips per unit)
uniform float uAngle;         // 0.0   (Rotation in radians. 1.57 = Horizontal)
uniform float uShapeMode;     // 0.0=Round, 1.0=Sharp, 2.0=Square
uniform float uVerticalShift; // 0.2   (Shatter amount)
uniform float uShowLines;     // New uniform for showing lines

// --- MARGINS (0.0 to 0.5) ---
// How much clean space to leave on each side
uniform float uMarginTop;     // 0.1
uniform float uMarginBottom;  // 0.1
uniform float uMarginLeft;    // 0.1
uniform float uMarginRight;   // 0.1

// --- OPTICAL SETTINGS ---
uniform float uRefraction;    // 0.1   (Lens strength)
uniform float uChroma;        // 0.04  (Rainbow edges)
uniform float uSpecular;      // 1.5   (Brightness of shine)

// --- HELPERS ---
float hash(float n) {
    return fract(sin(n) * 43758.5453123);
}

// 2D Rotation Matrix
mat2 rotate2d(float a) {
    float s = sin(a);
    float c = cos(a);
    return mat2(c, -s, s, c);
}

void mainImage(const in vec4 inputColor, const in vec2 uv, out vec4 outputColor) {

    // 1. GET SCROLL STRENGTH
    float progress = e0E0E0Intensity;

    // Safety
    if (progress <= 0.001 || progress >= 0.999) {
        outputColor = texture2D(uPreviousFrame, uv);
        return;
    }

    // Master Strength Curve
    float strength = smoothstep(0.0, 0.2, progress) * (1.0 - smoothstep(0.8, 1.0, progress));

    // 2. CALCULATE MARGIN MASK
    // Create a box where the effect is active
    float maskX = smoothstep(uMarginLeft, uMarginLeft + 0.01, uv.x) * 
                  (1.0 - smoothstep(1.0 - uMarginRight - 0.01, 1.0 - uMarginRight, uv.x));

    float maskY = smoothstep(uMarginBottom, uMarginBottom + 0.01, uv.y) * 
                  (1.0 - smoothstep(1.0 - uMarginTop - 0.01, 1.0 - uMarginTop, uv.y));

    float areaMask = maskX * maskY;

    // If we are outside the margins, strength becomes 0
    float localStrength = strength * areaMask;

    // Optimization: If in margin, draw clean
    if (localStrength < 0.001) {
        outputColor = texture2D(uPreviousFrame, uv);
        return;
    }

    // 3. ROTATION & COORDINATES
    vec2 aspect = vec2(uResolution.x / uResolution.y, 1.0);
    vec2 center = vec2(0.5);

    // Correct aspect so rotation doesn't squash the strips
    vec2 p = (uv - center) * aspect;
    p *= rotate2d(uAngle); // Rotate the coordinate system

    // 4. GENERATE STRIPS
    float stripPos = p.x * uDensity;
    float stripID = floor(stripPos);
    float localX = fract(stripPos); // 0.0 to 1.0

    // 5. SHAPE PROFILE LOGIC
    // We calculate the "Slope" (Normal) of the glass surface
    float slope = 0.0;
    float lighting = 0.0;

    if (uShapeMode < 0.5) { 
        // --- MODE 0: ROUND (Cylinder) ---
        // Map 0..1 to -1..1
        float curve = (localX - 0.5) * 2.0;
        slope = curve; 
        // Fake round lighting: bright center, dark edges
        lighting = pow(1.0 - abs(curve), 3.0); 
    } 
    else if (uShapeMode < 1.5) {
        // --- MODE 1: SHARP (Prism/Triangle) ---
        // Slopes linearly from -1 to 1
        slope = (localX - 0.5) * 2.0;
        // Sharp reflection on one facet
        lighting = step(0.9, abs(slope));
    } 
    else {
        // --- MODE 2: SQUARE (Louver) ---
        // Flat surface, only refracts at edges
        // Slope is 0 in middle, extreme at edges
        slope = 0.0; 
        if (localX < 0.1) slope = -1.0;
        if (localX > 0.9) slope = 1.0;
        lighting = step(0.9, localX); // Highlight edge
    }

    // 6. CALCULATE DISTORTION VECTORS
    // "Refraction" happens perpendicular to the strip (p.x axis in rotated space)
    // "Shatter" happens parallel to the strip (p.y axis in rotated space)

    vec2 offset = vec2(0.0);

    // Refract based on shape slope
    offset.x = -slope * uRefraction * localStrength;

    // Shatter/Shift based on ID
    float shatter = (hash(stripID) - 0.5) * uVerticalShift * localStrength;
    offset.y = shatter;

    // Rotate offset BACK to screen space
    offset *= rotate2d(-uAngle);

    // 7. SAMPLE & CHROMA
    vec2 finalUV = uv + offset;

    // Chromatic Aberration based on slope steepness
    float chromaAmt = uChroma * localStrength * abs(slope);

    vec3 col;
    col.r = texture2D(uPreviousFrame, finalUV + vec2(chromaAmt, 0.0)).r;
    col.g = texture2D(uPreviousFrame, finalUV).g;
    col.b = texture2D(uPreviousFrame, finalUV - vec2(chromaAmt, 0.0)).b;

    // 8. ADD LIGHTING
    // Specular shine based on the shape profile calculated earlier
    col += vec3(lighting * uSpecular * localStrength);

    // Conditionally remove darkening at edges based on uShowLines
    if (uShowLines < 0.5) { // If uShowLines is 0, remove darkening
        float edgeDarkness = smoothstep(0.8, 1.0, abs((localX - 0.5) * 2.0));
        col *= 1.0 - (edgeDarkness * 0.3 * localStrength);
    }

    // 9. MIX MARGINS
    // Blend the glass effect with the clean image at the margin edges
    vec3 original = texture2D(uPreviousFrame, uv).rgb;
    col = mix(original, col, areaMask);

    // Compiler Guard
    col.r += e0E0E0Intensity * 0.000001;

    outputColor = vec4(col, 1.0);
}
